    47→    public void ConfigureServices(IServiceCollection services)
    48→    {
    49→        ServiceProvider sp = Build(services);
    50→        IConfigProvider? configProvider = sp.GetService<IConfigProvider>() ?? throw new ApplicationException($"{nameof(IConfigProvider)} could not be resolved");
    51→        IJsonRpcConfig jsonRpcConfig = configProvider.GetConfig<IJsonRpcConfig>();
    52→
    53→        services.Configure<KestrelServerOptions>(options =>
    54→        {
    55→            options.Limits.MaxRequestBodySize = jsonRpcConfig.MaxRequestBodySize;
    56→            options.ConfigureHttpsDefaults(co => co.SslProtocols |= SslProtocols.Tls13);
    57→            options.ConfigureEndpointDefaults(listenOptions =>
    58→            {
    59→                listenOptions.Protocols = HttpProtocols.Http1;
    60→                listenOptions.DisableAltSvcHeader = true;
    61→            });
    62→        });
    63→        Bootstrap.Instance.RegisterJsonRpcServices(services);
    64→
    65→        services.AddCors(options => options.AddDefaultPolicy(builder => builder
    66→            .AllowAnyMethod()
    67→            .AllowAnyHeader()
    68→            .WithOrigins(jsonRpcConfig.CorsOrigins)));
    69→
    70→        services.AddResponseCompression(options =>
    71→        {
    72→            options.Providers.Add<BrotliCompressionProvider>();
    73→            options.Providers.Add<GzipCompressionProvider>();
    74→            options.MimeTypes = ResponseCompressionDefaults.MimeTypes;
    75→            options.EnableForHttps = true;
    76→        });
    77→    }
    78→
    79→    private static ServiceProvider Build(IServiceCollection services) => services.BuildServiceProvider();
