    82→    public void Configure(IApplicationBuilder app)
    83→    {
    84→        IServiceProvider services = app.ApplicationServices;
    85→        Configure(
    86→            app,
    87→            services.GetRequiredService<IWebHostEnvironment>(),
    88→            services.GetRequiredService<IJsonRpcProcessor>(),
    89→            services.GetRequiredService<IJsonRpcService>(),
    90→            services.GetRequiredService<IJsonRpcLocalStats>(),
    91→            services.GetRequiredService<IJsonSerializer>(),
    92→            services.GetRequiredService<ApplicationLifetime>());
    93→    }
    94→
    95→    public void Configure(IApplicationBuilder app, IWebHostEnvironment env, IJsonRpcProcessor jsonRpcProcessor, IJsonRpcService jsonRpcService, IJsonRpcLocalStats jsonRpcLocalStats, IJsonSerializer jsonSerializer, ApplicationLifetime lifetime)
    96→    {
    97→        if (env.IsDevelopment())
    98→        {
    99→            app.UseDeveloperExceptionPage();
   100→        }
   101→
   102→        app.UseRouting();
   103→        app.UseCors();
   104→
   105→        IConfigProvider? configProvider = app.ApplicationServices.GetService<IConfigProvider>();
   106→        IRpcAuthentication? rpcAuthentication = app.ApplicationServices.GetService<IRpcAuthentication>();
   107→
   108→        if (configProvider is null)
   109→        {
   110→            throw new ApplicationException($"{nameof(IConfigProvider)} has not been loaded properly");
   111→        }
   112→
   113→        ILogManager? logManager = app.ApplicationServices.GetService<ILogManager>() ?? NullLogManager.Instance;
   114→        ILogger logger = logManager.GetClassLogger();
   115→        IInitConfig initConfig = configProvider.GetConfig<IInitConfig>();
   116→        IJsonRpcConfig jsonRpcConfig = configProvider.GetConfig<IJsonRpcConfig>();
   117→        IJsonRpcUrlCollection jsonRpcUrlCollection = app.ApplicationServices.GetRequiredService<IJsonRpcUrlCollection>();
   118→        IHealthChecksConfig healthChecksConfig = configProvider.GetConfig<IHealthChecksConfig>();
   119→
   120→        // If request is local, don't use response compression,
   121→        // as it allocates a lot, but doesn't improve much for loopback
   122→        app.UseWhen(ctx =>
   123→            !IsLocalhost(ctx.Connection.RemoteIpAddress),
   124→            builder => builder.UseResponseCompression());
   125→
   126→        if (initConfig.WebSocketsEnabled)
   127→        {
   128→            app.UseWebSockets(new WebSocketOptions());
   129→            app.UseWhen(ctx =>
   130→                ctx.WebSockets.IsWebSocketRequest &&
   131→                jsonRpcUrlCollection.TryGetValue(ctx.Connection.LocalPort, out JsonRpcUrl jsonRpcUrl) &&
   132→                jsonRpcUrl.RpcEndpoint.HasFlag(RpcEndpoint.Ws),
   133→            builder => builder.UseWebSocketsModules());
   134→        }
   135→
   136→        app.UseEndpoints(endpoints =>
   137→        {
   138→            if (healthChecksConfig.Enabled)
   139→            {
   140→                try
   141→                {
   142→                    endpoints.MapHealthChecks(healthChecksConfig.Slug, new HealthCheckOptions()
   143→                    {
   144→                        Predicate = _ => true,
   145→                        ResponseWriter = UIResponseWriter.WriteHealthCheckUIResponse
   146→                    });
   147→                    if (healthChecksConfig.UIEnabled)
   148→                    {
   149→                        endpoints.MapHealthChecksUI(setup => setup.AddCustomStylesheet(Path.Combine(AppDomain.CurrentDomain.BaseDirectory!, "nethermind.css")));
   150→                    }
   151→                }
   152→                catch (Exception e)
   153→                {
   154→                    if (logger.IsError) logger.Error("Unable to initialize health checks. Check if you have Nethermind.HealthChecks.dll in your plugins folder.", e);
   155→                }
   156→
   157→                IServiceProvider services = app.ApplicationServices;
   158→                endpoints.MapDataFeeds(lifetime);
   159→            }
   160→        });
   161→
   162→        app.MapWhen(
   163→            (ctx) => ctx.Request.ContentType?.Contains("application/json") ?? false,
   164→            builder => builder.Run(async ctx =>
   165→        {
   166→            var method = ctx.Request.Method;
   167→            if (method is not "POST" and not "GET")
   168→            {
   169→                ctx.Response.StatusCode = (int)HttpStatusCode.MethodNotAllowed;
   170→                return;
   171→            }
   172→
   173→            if (jsonRpcProcessor.ProcessExit.IsCancellationRequested)
   174→            {
   175→                ctx.Response.StatusCode = (int)HttpStatusCode.ServiceUnavailable;
   176→                return;
   177→            }
   178→
   179→            if (!jsonRpcUrlCollection.TryGetValue(ctx.Connection.LocalPort, out JsonRpcUrl jsonRpcUrl) || !jsonRpcUrl.RpcEndpoint.HasFlag(RpcEndpoint.Http))
   180→            {
   181→                ctx.Response.StatusCode = (int)HttpStatusCode.NotFound;
   182→                return;
   183→            }
   184→
   185→            if (jsonRpcUrl.IsAuthenticated)
   186→            {
   187→                if (!await rpcAuthentication!.Authenticate(ctx.Request.Headers.Authorization))
   188→                {
   189→                    await PushErrorResponse(StatusCodes.Status401Unauthorized, ErrorCodes.InvalidRequest, "Authentication error");
   190→                    return;
   191→                }
   192→            }
   193→
   194→            if (method == "GET" && ctx.Request.Headers.Accept.Count > 0 &&
   195→                !ctx.Request.Headers.Accept[0].Contains("text/html", StringComparison.Ordinal))
   196→            {
   197→                await ctx.Response.WriteAsync("Nethermind JSON RPC");
   198→            }
   199→            else if (ctx.Request.ContentType?.Contains("application/json") == false)
   200→            {
   201→                await PushErrorResponse(StatusCodes.Status415UnsupportedMediaType, ErrorCodes.InvalidRequest, "Missing 'application/json' Content-Type header");
   202→            }
   203→            else
   204→            {
   205→                if (jsonRpcUrl.MaxRequestBodySize is not null)
   206→                    ctx.Features.Get<IHttpMaxRequestBodySizeFeature>().MaxRequestBodySize = jsonRpcUrl.MaxRequestBodySize;
   207→
   208→                long startTime = Stopwatch.GetTimestamp();
   209→                CountingPipeReader request = new(ctx.Request.BodyReader);
   210→                try
   211→                {
   212→                    using JsonRpcContext jsonRpcContext = JsonRpcContext.Http(jsonRpcUrl);
   213→                    await foreach (JsonRpcResult result in jsonRpcProcessor.ProcessAsync(request, jsonRpcContext))
   214→                    {
   215→                        using (result)
   216→                        {
   217→                            await using Stream stream = jsonRpcConfig.BufferResponses ? RecyclableStream.GetStream("http") : null;
   218→                            CountingWriter resultWriter = stream is not null ? new CountingStreamPipeWriter(stream) : new CountingPipeWriter(ctx.Response.BodyWriter);
   219→                            try
   220→                            {
   221→                                ctx.Response.ContentType = "application/json";
   222→                                ctx.Response.StatusCode = GetStatusCode(result);
   223→
   224→                                if (result.IsCollection)
   225→                                {
   226→                                    resultWriter.Write(_jsonOpeningBracket);
   227→                                    bool first = true;
   228→                                    JsonRpcBatchResultAsyncEnumerator enumerator = result.BatchedResponses.GetAsyncEnumerator(CancellationToken.None);
   229→                                    try
   230→                                    {
   231→                                        while (await enumerator.MoveNextAsync())
   232→                                        {
   233→                                            JsonRpcResult.Entry entry = enumerator.Current;
   234→                                            using (entry)
   235→                                            {
   236→                                                if (!first)
   237→                                                {
   238→                                                    resultWriter.Write(_jsonComma);
   239→                                                }
   240→
   241→                                                first = false;
   242→                                                await jsonSerializer.SerializeAsync(resultWriter, entry.Response);
   243→                                                _ = jsonRpcLocalStats.ReportCall(entry.Report);
   244→
   245→                                                // We reached the limit and don't want to responded to more request in the batch
   246→                                                if (!jsonRpcContext.IsAuthenticated && resultWriter.WrittenCount > jsonRpcConfig.MaxBatchResponseBodySize)
   247→                                                {
   248→                                                    if (logger.IsWarn)
   249→                                                        logger.Warn(
   250→                                                            $"The max batch response body size exceeded. The current response size {resultWriter.WrittenCount}, and the config setting is JsonRpc.{nameof(jsonRpcConfig.MaxBatchResponseBodySize)} = {jsonRpcConfig.MaxBatchResponseBodySize}");
   251→                                                    enumerator.IsStopped = true;
   252→                                                }
   253→                                            }
   254→                                        }
   255→                                    }
   256→                                    finally
   257→                                    {
   258→                                        await enumerator.DisposeAsync();
   259→                                    }
   260→
   261→                                    resultWriter.Write(_jsonClosingBracket);
   262→                                }
   263→                                else
   264→                                {
   265→                                    await jsonSerializer.SerializeAsync(resultWriter, result.Response);
   266→                                }
   267→                                await resultWriter.CompleteAsync();
   268→                                if (stream is not null)
   269→                                {
   270→                                    ctx.Response.ContentLength = resultWriter.WrittenCount;
   271→                                    stream.Seek(0, SeekOrigin.Begin);
   272→                                    await stream.CopyToAsync(ctx.Response.Body);
   273→                                }
   274→                            }
   275→                            catch (Exception e) when (e.InnerException is OperationCanceledException)
   276→                            {
   277→                                await SerializeTimeoutException(resultWriter);
   278→                            }
   279→                            catch (OperationCanceledException)
   280→                            {
   281→                                await SerializeTimeoutException(resultWriter);
   282→                            }
   283→                            finally
   284→                            {
   285→                                await ctx.Response.CompleteAsync();
   286→                            }
   287→
